using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GlassHeartOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/GlassHeartOmenData")]
public class GlassHeartOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.GlassHeartOmenAction = delegate
		{
			if (AlreadyUsed)
			{
				return false;
			}
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentPlayerHearts == 1)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				omenInstance.DisableOmen();
				ToggleAlreadyUsed(toggle: true);
				return true;
			}
			return false;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.GlassHeartOmenAction = null;
	}
}
